pgp_get_card_features(sc_card_t *card)
{
        struct pgp_priv_data *priv = DRVDATA(card);
        u8 *hist_bytes = card->reader->atr_info.hist_bytes;
        size_t hist_bytes_len = card->reader->atr_info.hist_bytes_len;
